      "capabilities": ["multicast_dns_resolution", "mDNS_publishing", "unicast_dns_stub_resolver", "service_registration_expiry"]
    },
    {
      "name": "DNS 服务发现 (DNS-SD)",
      "description": "基于 DNS 协议的服务发现框架 (RFC 6763)，支持浏览可用服务类型、解析服务实例到具体 IP:端口、注册新服务、枚举推荐浏览/注册域。通过 dns-sd 命令行工具和 dns_sd.h C API 暴露。",
      "capabilities": ["service_browsing", "service_resolution", "service_registration", "domain_enumeration"]
